import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getMyAuctions, getMyBids } from '../services/api';

function Dashboard() {
  const [myAuctions, setMyAuctions] = useState([]);
  const [myBids, setMyBids] = useState([]);

  useEffect(() => {
    Promise.all([getMyAuctions(), getMyBids()]).then(([auctions, bids]) => {
      setMyAuctions(auctions.data.results || auctions.data);
      setMyBids(bids.data.results || bids.data);
    });
  }, []);

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Dashboard</h2>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
        <section style={{ border: '1px solid #e5e7eb', borderRadius: 12, padding: '1rem' }}>
          <h3>My auctions</h3>
          {myAuctions.length === 0 ? <p>No auctions yet.</p> : myAuctions.map((auction) => (
            <div key={auction.id}>
              <Link to={`/auction/${auction.id}`}>{auction.title}</Link>
            </div>
          ))}
        </section>
        <section style={{ border: '1px solid #e5e7eb', borderRadius: 12, padding: '1rem' }}>
          <h3>My bids</h3>
          {myBids.length === 0 ? <p>No bids yet.</p> : myBids.map((auction) => (
            <div key={auction.id}>
              <Link to={`/auction/${auction.id}`}>{auction.title}</Link>
            </div>
          ))}
        </section>
      </div>
    </div>
  );
}

export default Dashboard;
