import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';
import { getProfile, updateProfile } from '../services/api';

function Profile() {
  const [profile, setProfile] = useState({ username: '', email: '', phone: '' });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    getProfile().then(({ data }) => setProfile(data));
  }, []);

  const handleChange = (e) => {
    setProfile({ ...profile, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { data } = await updateProfile(profile);
      setProfile(data);
      toast.success('Profile updated');
    } catch (error) {
      toast.error('Profile update failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: 500, margin: '2rem auto', padding: '2rem', border: '1px solid #e5e7eb', borderRadius: 12 }}>
      <h2>Profile</h2>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: 12 }}>
          <label>Username</label>
          <input name="username" value={profile.username || ''} onChange={handleChange} style={{ width: '100%', padding: 8, marginTop: 6 }} />
        </div>
        <div style={{ marginBottom: 12 }}>
          <label>Email</label>
          <input type="email" name="email" value={profile.email || ''} onChange={handleChange} style={{ width: '100%', padding: 8, marginTop: 6 }} />
        </div>
        <div style={{ marginBottom: 12 }}>
          <label>Phone</label>
          <input name="phone" value={profile.phone || ''} onChange={handleChange} style={{ width: '100%', padding: 8, marginTop: 6 }} />
        </div>
        <button type="submit" disabled={loading} style={{ width: '100%', padding: 10, background: '#111827', color: '#fff', border: 'none', borderRadius: 8 }}>
          {loading ? 'Saving...' : 'Update profile'}
        </button>
      </form>
    </div>
  );
}

export default Profile;
