import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { toast } from 'react-toastify';
import { getAuctionDetail, placeBid } from '../services/api';

function AuctionDetail() {
  const { id } = useParams();
  const [auction, setAuction] = useState(null);
  const [bidAmount, setBidAmount] = useState('');
  const [loading, setLoading] = useState(false);

  const loadAuction = () => {
    getAuctionDetail(id).then(({ data }) => {
      setAuction(data);
      setBidAmount((Number(data.current_highest_bid || data.base_price) + 5).toString());
    });
  };

  useEffect(() => {
    loadAuction();
  }, [id]);

  const handleBid = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await placeBid(id, bidAmount);
      toast.success('Bid placed successfully');
      loadAuction();
    } catch (error) {
      toast.error(error?.response?.data?.detail || 'Bid failed');
    } finally {
      setLoading(false);
    }
  };

  if (!auction) return <p style={{ padding: '2rem' }}>Loading...</p>;

  return (
    <div style={{ padding: '2rem', maxWidth: 900, margin: '0 auto' }}>
      <h2>{auction.title}</h2>
      <p>{auction.description}</p>
      <p><strong>Seller:</strong> {auction.seller_username}</p>
      <p><strong>Category:</strong> {auction.category}</p>
      <p><strong>Current bid:</strong> ${auction.current_highest_bid}</p>
      <p><strong>Base price:</strong> ${auction.base_price}</p>

      <form onSubmit={handleBid} style={{ marginTop: '1.5rem', maxWidth: 320 }}>
        <label>Bid amount</label>
        <input type="number" step="0.01" value={bidAmount} onChange={(e) => setBidAmount(e.target.value)} style={{ width: '100%', padding: 8, marginTop: 6 }} required />
        <button type="submit" disabled={loading} style={{ width: '100%', marginTop: 12, padding: 10, background: '#111827', color: '#fff', border: 'none', borderRadius: 8 }}>
          {loading ? 'Placing bid...' : 'Place bid'}
        </button>
      </form>

      <div style={{ marginTop: '2rem' }}>
        <h3>Recent bids</h3>
        {(auction.bid_history || []).length === 0 ? <p>No bids yet.</p> : (
          <ul>
            {auction.bid_history.map((bid, index) => (
              <li key={`${bid.bidder}-${index}`}>{bid.bidder}: ${bid.amount}</li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default AuctionDetail;
