import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { createAuction } from '../services/api';

function CreateAuction() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    title: '',
    description: '',
    category: 'general',
    condition: 'used',
    base_price: '10',
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const payload = new FormData();
      Object.entries(form).forEach(([key, value]) => payload.append(key, value));
      const { data } = await createAuction(payload);
      toast.success('Auction created');
      navigate(`/auction/${data.id}`);
    } catch (error) {
      toast.error('Could not create auction');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: 600, margin: '2rem auto', padding: '2rem', border: '1px solid #e5e7eb', borderRadius: 12 }}>
      <h2>Create Auction</h2>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: 12 }}>
          <label>Title</label>
          <input name="title" value={form.title} onChange={handleChange} style={{ width: '100%', padding: 8, marginTop: 6 }} required />
        </div>
        <div style={{ marginBottom: 12 }}>
          <label>Description</label>
          <textarea name="description" value={form.description} onChange={handleChange} rows={4} style={{ width: '100%', padding: 8, marginTop: 6 }} required />
        </div>
        <div style={{ display: 'flex', gap: 12 }}>
          <div style={{ flex: 1 }}>
            <label>Category</label>
            <select name="category" value={form.category} onChange={handleChange} style={{ width: '100%', padding: 8, marginTop: 6 }}>
              <option value="general">General</option>
              <option value="electronics">Electronics</option>
              <option value="fashion">Fashion</option>
              <option value="home">Home</option>
            </select>
          </div>
          <div style={{ flex: 1 }}>
            <label>Condition</label>
            <select name="condition" value={form.condition} onChange={handleChange} style={{ width: '100%', padding: 8, marginTop: 6 }}>
              <option value="new">New</option>
              <option value="used">Used</option>
              <option value="refurbished">Refurbished</option>
            </select>
          </div>
        </div>
        <div style={{ marginTop: 12 }}>
          <label>Base price</label>
          <input type="number" step="0.01" name="base_price" value={form.base_price} onChange={handleChange} style={{ width: '100%', padding: 8, marginTop: 6 }} required />
        </div>
        <button type="submit" disabled={loading} style={{ width: '100%', marginTop: 18, padding: 10, background: '#111827', color: '#fff', border: 'none', borderRadius: 8 }}>
          {loading ? 'Creating...' : 'Create auction'}
        </button>
      </form>
    </div>
  );
}

export default CreateAuction;
