import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getAuctions } from '../services/api';

function AuctionList() {
  const [auctions, setAuctions] = useState([]);

  useEffect(() => {
    getAuctions().then(({ data }) => setAuctions(data.results || data)).catch(() => setAuctions([]));
  }, []);

  return (
    <div className="content-shell">
      <section className="hero-banner">
        <div>
          <p className="eyebrow">Live marketplace</p>
          <h1>Bid on standout finds.</h1>
          <p className="hero-copy">Discover premium goods, discover fresh deals, and place your next winning offer in a polished modern auction experience.</p>
        </div>
        <div className="hero-metric">
          <span>{auctions.length}</span>
          <small>live listings</small>
        </div>
      </section>

      <section className="section-header">
        <h2>Active auctions</h2>
      </section>

      <div className="auction-grid">
        {auctions.length === 0 ? (
          <div className="empty-card">
            <div className="empty-icon">📦</div>
            <p>No auctions yet.</p>
          </div>
        ) : (
          auctions.map((auction) => (
            <article key={auction.id} className="auction-card">
              <div className="auction-card-image">🎯</div>
              <div className="auction-card-body">
                <div className="auction-card-topline">
                  <span className="status-pill">Live</span>
                </div>
                <h3 className="auction-card-title">{auction.title}</h3>
                <p className="auction-card-description">{auction.description?.slice(0, 120)}</p>
                <div className="auction-card-meta">
                  <span><strong>Seller:</strong> {auction.seller_username}</span>
                </div>
                <div className="auction-card-price-row">
                  <div>
                    <label>Current bid</label>
                    <strong>${auction.current_highest_bid}</strong>
                  </div>
                  <div>
                    <label>Base price</label>
                    <strong>${auction.base_price}</strong>
                  </div>
                </div>
                <div className="auction-card-footer">
                  <Link to={`/auction/${auction.id}`} className="detail-link">View details</Link>
                </div>
              </div>
            </article>
          ))
        )}
      </div>
    </div>
  );
}

export default AuctionList;
